import { NotFoundError, ValidationError } from "../domain/errors";
import {
  Clock,
  IdGenerator,
  ProjectRepository,
  TaskFilter,
  TaskRepository,
  UserRepository,
} from "../domain/repositories";
import { Task, TaskStatus } from "../domain/task";

export interface AddTaskCommand {
  projectId: string;
  title: string;
  description: string;
  dueDate?: Date | null;
  status?: TaskStatus;
  assigneeId?: string | null;
}

export class TaskService {
  constructor(
    private readonly tasks: TaskRepository,
    private readonly projects: ProjectRepository,
    private readonly users: UserRepository,
    private readonly ids: IdGenerator,
    private readonly clock: Clock,
  ) {}

  addTask(command: AddTaskCommand): Task {
    this.requireProject(command.projectId);
    const assigneeId = command.assigneeId ?? null;
    if (assigneeId !== null) {
      this.requireUser(assigneeId);
    }
    const task = Task.create({
      id: this.ids.next(),
      projectId: command.projectId,
      title: command.title,
      description: command.description,
      dueDate: command.dueDate ?? null,
      status: command.status ?? "todo",
      assigneeId,
      createdAt: this.clock.now(),
    });
    this.tasks.save(task);
    return task;
  }

  getTask(projectId: string, taskId: string): Task {
    this.requireProject(projectId);
    const task = this.tasks.findById(taskId);
    if (!task || task.projectId !== projectId) {
      throw new NotFoundError("Task", taskId);
    }
    return task;
  }

  assignTask(projectId: string, taskId: string, userId: string): Task {
    const task = this.getTask(projectId, taskId);
    this.requireUser(userId);
    task.assignTo(userId);
    this.tasks.save(task);
    return task;
  }

  markTaskDone(projectId: string, taskId: string): Task {
    const task = this.getTask(projectId, taskId);
    task.markDone();
    this.tasks.save(task);
    return task;
  }

  listTasks(projectId: string, filter: TaskFilter = {}): Task[] {
    this.requireProject(projectId);
    return this.tasks.findByProject(projectId, filter);
  }

  private requireProject(projectId: string): void {
    if (!this.projects.findById(projectId)) {
      throw new NotFoundError("Project", projectId);
    }
  }

  private requireUser(userId: string): void {
    if (!this.users.findById(userId)) {
      throw new ValidationError(`Assignee '${userId}' is not an existing user`);
    }
  }
}

